class Solution {
    public boolean isPossible(int[] nums) {
        java.util.Map<Integer, Integer> remaining = new java.util.HashMap<>();
        java.util.Map<Integer, Integer> waiting = new java.util.HashMap<>();
        for (int value : nums) {
            remaining.merge(value, 1, Integer::sum);
        }

        for (int value : nums) {
            if (remaining.getOrDefault(value, 0) == 0) {
                continue;
            }
            remaining.merge(value, -1, Integer::sum);

            if (waiting.getOrDefault(value, 0) > 0) {
                waiting.merge(value, -1, Integer::sum);
                waiting.merge(value + 1, 1, Integer::sum);
            } else if (remaining.getOrDefault(value + 1, 0) > 0
                    && remaining.getOrDefault(value + 2, 0) > 0) {
                remaining.merge(value + 1, -1, Integer::sum);
                remaining.merge(value + 2, -1, Integer::sum);
                waiting.merge(value + 3, 1, Integer::sum);
            } else {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public boolean isPossible(int[] nums) {
        java.util.PriorityQueue<int[]> active = new java.util.PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) {
                return Integer.compare(a[0], b[0]);
            }
            return Integer.compare(a[1], b[1]);
        });

        for (int value : nums) {
            while (!active.isEmpty() && active.peek()[0] + 1 < value) {
                if (active.poll()[1] < 3) {
                    return false;
                }
            }

            if (!active.isEmpty() && active.peek()[0] + 1 == value) {
                int[] sequence = active.poll();
                active.offer(new int[]{value, sequence[1] + 1});
            } else {
                active.offer(new int[]{value, 1});
            }
        }

        while (!active.isEmpty()) {
            if (active.poll()[1] < 3) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public boolean isPossible(int[] nums) {
        int previous = Integer.MIN_VALUE;
        int lengthOne = 0;
        int lengthTwo = 0;
        int lengthThreeOrMore = 0;

        int index = 0;
        while (index < nums.length) {
            int value = nums[index];
            int count = 0;
            while (index < nums.length && nums[index] == value) {
                count++;
                index++;
            }

            int nextLengthOne;
            int nextLengthTwo;
            int nextLengthThreeOrMore;
            if (previous != Integer.MIN_VALUE && value != previous + 1) {
                if (lengthOne > 0 || lengthTwo > 0) {
                    return false;
                }
                nextLengthOne = count;
                nextLengthTwo = 0;
                nextLengthThreeOrMore = 0;
            } else {
                if (count < lengthOne + lengthTwo) {
                    return false;
                }
                int remaining = count - lengthOne - lengthTwo;
                nextLengthOne = Math.max(0, remaining - lengthThreeOrMore);
                nextLengthTwo = lengthOne;
                nextLengthThreeOrMore = lengthTwo + Math.min(lengthThreeOrMore, remaining);
            }

            previous = value;
            lengthOne = nextLengthOne;
            lengthTwo = nextLengthTwo;
            lengthThreeOrMore = nextLengthThreeOrMore;
        }

        return lengthOne == 0 && lengthTwo == 0;
    }
}

class Solution {
    public boolean isPossible(int[] nums) {
        java.util.Map<Integer, java.util.PriorityQueue<Integer>> byTail = new java.util.HashMap<>();
        for (int value : nums) {
            java.util.PriorityQueue<Integer> previous = byTail.get(value - 1);
            int newLength = 1;
            if (previous != null && !previous.isEmpty()) {
                newLength = previous.poll() + 1;
            }
            byTail.computeIfAbsent(value, key -> new java.util.PriorityQueue<>()).offer(newLength);
        }

        for (java.util.PriorityQueue<Integer> lengths : byTail.values()) {
            while (!lengths.isEmpty()) {
                if (lengths.poll() < 3) {
                    return false;
                }
            }
        }
        return true;
    }
}
